/* The team in the OnePage and the community (round 40, run after part 135; before or after part 320): two functions that answer, inside a row level security policy, whether the signed in person is on a store's team with a permission. public.team_store_ids(area) returns the stores (creators.id) where the signed in account is an active member whose permissions hold that area; public.team_can(store, area) answers for one store. Both read store_team_members.permissions through to_jsonb, so they work before part 320 has added the column (and then answer no, as a row from before part 320 holds no area but Orders) and need nothing run again after it. Both are security definer, answer only for auth.uid() (never for a visitor), and only for the twelve area keys. One policy uses them: "storelib team reads store products", so the OnePage editor's product picker, opened by a team member with OnePage, lists the store's products, drafts too, as it does for the owner. It only adds reading; nothing is written through it and nothing changes for the owner or for visitors. The OnePage's own reads and writes go through the server with the member's permissions checked on each request (lib/team/onepage.ts), and the communities are server only already (lib/communities/server/team.ts). Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 319: store_team_members is not here yet; run part 135 first, then this again.'; RETURN; END IF; EXECUTE $f$create or replace function public.team_store_ids(p_area text) returns setof uuid language sql stable security definer set search_path = public as $b$ select m.creator_id from public.store_team_members m where (select auth.uid()) is not null and m.user_id = (select auth.uid()) and m.status = 'active' and p_area = any (array['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts_billing']) and coalesce(to_jsonb(m) -> 'permissions', '[]'::jsonb) ? p_area $b$$f$; EXECUTE $f$create or replace function public.team_can(p_creator uuid, p_area text) returns boolean language sql stable security definer set search_path = public as $b$ select p_creator is not null and exists (select 1 from public.team_store_ids(p_area) s where s = p_creator) $b$$f$; COMMENT ON FUNCTION public.team_store_ids(text) IS 'The stores where the signed in account is an active team member holding this area (store_team_members.permissions, part 320). For row level security policies (part 319).'; COMMENT ON FUNCTION public.team_can(uuid, text) IS 'Whether the signed in account is an active team member of this store holding this area (part 319).'; REVOKE ALL ON FUNCTION public.team_store_ids(text) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_can(uuid, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_store_ids(text) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_can(uuid, text) TO authenticated, service_role; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 319: there is no products table here, no policy to add.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team reads store products') THEN CREATE POLICY "storelib team reads store products" ON public.products FOR SELECT TO authenticated USING (creator_id IN (SELECT public.team_store_ids('onepage'))); END IF; END $do$;
notify pgrst, 'reload schema';
